#!/usr/bin/env bash
set -euo pipefail
ROOT="${GITHUB_WORKSPACE:?}"; PORT="$ROOT/rpg-series-port/rogues-forge-1.20.1"; TMP="${RUNNER_TEMP:-/tmp}/paladins-first-compile"; RUN="$PORT/forge/run"; FRESH="$PORT/.fresh-rogues-forge-server"
CLIENT_LOG="$PORT/rogues-player-behavior.log"; CLIENT_LATEST="$RUN/logs/latest.log"; SERVER_LOG="$PORT/rogues-player-server.log"; SERVER_LATEST="$FRESH/logs/latest.log"; FIFO="$FRESH/rogues-player-console.fifo"; ROBOT_DIR="${RUNNER_TEMP:-/tmp}/rogues-input-robot"; QA_HELPER="$PORT/forge/src/main/java/net/rogues/forge/client/RoguesQaAutoConnect.java"; QA_HELPER_CLASS="$PORT/forge/build/classes/java/main/net/rogues/forge/client/RoguesQaAutoConnect.class"
CLIENT_PID=''; SERVER_PID=''; XVFB_PID=''
cleanup(){ exec 9>&- 2>/dev/null || true; if [[ -n "$CLIENT_PID" ]] && kill -0 "$CLIENT_PID" 2>/dev/null; then kill -TERM "$CLIENT_PID" 2>/dev/null || true; sleep 1; kill -KILL "$CLIENT_PID" 2>/dev/null || true; wait "$CLIENT_PID" 2>/dev/null || true; fi; if [[ -n "$SERVER_PID" ]] && kill -0 "$SERVER_PID" 2>/dev/null; then kill -TERM "$SERVER_PID" 2>/dev/null || true; sleep 1; kill -KILL "$SERVER_PID" 2>/dev/null || true; wait "$SERVER_PID" 2>/dev/null || true; fi; if [[ -n "$XVFB_PID" ]] && kill -0 "$XVFB_PID" 2>/dev/null; then kill -TERM "$XVFB_PID" 2>/dev/null || true; wait "$XVFB_PID" 2>/dev/null || true; fi; rm -f "$FIFO" "$QA_HELPER" "$QA_HELPER_CLASS"; }; trap cleanup EXIT
wait_marker(){ local marker="$1" timeout_seconds="$2" label="$3" deadline=$((SECONDS+timeout_seconds)); local fatal='MixinApplyError|InvalidMixinException|MixinTransformerError|Failed to create mod instance|NoClassDefFoundError|ClassNotFoundException|Exception in thread "Render thread"|The game crashed|Failed to load datapacks|Missing or unsupported mandatory dependencies|Failed to start the minecraft server|Exception in server tick loop|Incompatible FML modded server|mismatched mod channel|Connection refused'; while (( SECONDS < deadline )); do if grep -Eiq "$fatal" "$CLIENT_LOG" "$CLIENT_LATEST" "$SERVER_LOG" "$SERVER_LATEST" 2>/dev/null; then echo "[Rogues player QA] fatal runtime signature during $label" >&2; tail -n 400 "$CLIENT_LOG" "$CLIENT_LATEST" "$SERVER_LOG" "$SERVER_LATEST" 2>/dev/null || true; return 1; fi; if grep -Fq "$marker" "$CLIENT_LOG" 2>/dev/null || grep -Fq "$marker" "$CLIENT_LATEST" 2>/dev/null || grep -Fq "$marker" "$SERVER_LOG" 2>/dev/null || grep -Fq "$marker" "$SERVER_LATEST" 2>/dev/null; then return 0; fi; if [[ -n "$SERVER_PID" ]] && ! kill -0 "$SERVER_PID" 2>/dev/null; then wait "$SERVER_PID" 2>/dev/null || true; tail -n 400 "$SERVER_LOG" "$SERVER_LATEST" 2>/dev/null || true; echo "[Rogues player QA] packaged server exited before $label marker: $marker" >&2; return 1; fi; if [[ -n "$CLIENT_PID" ]] && ! kill -0 "$CLIENT_PID" 2>/dev/null; then wait "$CLIENT_PID" 2>/dev/null || true; tail -n 400 "$CLIENT_LOG" "$CLIENT_LATEST" 2>/dev/null || true; echo "[Rogues player QA] native client exited before $label marker: $marker" >&2; return 1; fi; sleep 1; done; tail -n 400 "$CLIENT_LOG" "$CLIENT_LATEST" "$SERVER_LOG" "$SERVER_LATEST" 2>/dev/null || true; echo "[Rogues player QA] timed out waiting for $label marker: $marker" >&2; return 1; }
send_cmd(){ printf '%s\n' "$1" >&9; }
pick_jar(){ local dir="$1" glob="$2"; local -a jars=(); mapfile -t jars < <(find "$dir" -maxdepth 1 -type f -name "$glob" ! -name '*sources*' ! -name '*dev-shadow*' ! -name '*javadoc*' -print | sort); (( ${#jars[@]} == 1 )) || { echo "[Rogues player QA] expected one $glob in $dir, found ${#jars[@]}" >&2; return 1; }; printf '%s\n' "${jars[0]}"; }
[[ -x "$FRESH/run.sh" && -f "$FRESH/world/level.dat" ]] || { echo '[Rogues player QA] certified packaged server/world missing' >&2; exit 1; }; [[ "$(find "$FRESH/mods" -maxdepth 1 -type f -name '*.jar' | wc -l | tr -d ' ')" = 9 ]] || { echo '[Rogues player QA] expected exact nine-mod packaged runtime' >&2; exit 1; }; EXPECTED_SHA="$(awk '{print $1}' "$PORT/rogues.sha256")"; [[ "$EXPECTED_SHA" = '9e8c880f55ab57d91148c0be702a431bad6e312900b25f65c9dbec266e3ca401' ]] || { echo '[Rogues player QA] certified release ledger drifted' >&2; exit 1; }; ROG_JAR="$(find "$FRESH/mods" -maxdepth 1 -type f -name 'rogues-forge-3.1.1+1.20.1.jar' -print -quit)"; [[ -f "$ROG_JAR" && "$(sha256sum "$ROG_JAR" | awk '{print $1}')" = "$EXPECTED_SHA" ]] || { echo '[Rogues player QA] packaged Rogues identity mismatch' >&2; exit 1; }; grep -Fq 'online-mode=false' "$FRESH/server.properties"
SPELL_POWER_COMMON="$(pick_jar "$ROOT/rpg-series-port/spell_power-forge-1.20.1/common/build/libs" '*-common-*.jar')"; SPELL_POWER_FORGE="$(pick_jar "$ROOT/rpg-series-port/spell_power-forge-1.20.1/forge/build/libs" '*-forge-*.jar')"; TINY_COMMON="$(pick_jar "$ROOT/rpg-series-port/tiny-config-forge-1.20.1/generated/common/build/libs" '*-common-*.jar')"; TINY_FORGE="$(pick_jar "$ROOT/rpg-series-port/tiny-config-forge-1.20.1/generated/forge/build/libs" '*-forge-*.jar')"; SPELL_ENGINE_COMMON="$(pick_jar "$ROOT/.spell-engine-build/common/build/libs" '*-common-*.jar')"; SPELL_ENGINE_FORGE="$ROOT/rpg-series-port/spell-engine-forge-1.20.1/spell_engine-forge-1.10.2+1.20.1.jar"; STRUCTURE_COMMON="$(pick_jar "$ROOT/rpg-series-port/structure_pool_api-forge-1.20.1/common/build/libs" '*-common-*.jar')"; STRUCTURE_FORGE="$(pick_jar "$ROOT/rpg-series-port/structure_pool_api-forge-1.20.1/forge/build/libs" '*-forge-*.jar')"; ARMOR_COMMON="$(pick_jar "$ROOT/rpg-series-port/armor-model-api-forge-1.20.1/generated/common/build/libs" '*-common-*.jar')"; ARMOR_FORGE="$(pick_jar "$ROOT/rpg-series-port/armor-model-api-forge-1.20.1/generated/forge/build/libs" '*-forge-*.jar')"; CLOTH_FORGE="$TMP/ext/cloth-config-forge-11.1.136.jar"; PLAYER_FORGE="$TMP/ext/player-animation-lib-forge-1.0.2+1.19.4.jar"; CURIOS_FORGE="$TMP/ext/curios-forge-5.14.1+1.20.1.jar"; for dep in "$SPELL_POWER_COMMON" "$SPELL_POWER_FORGE" "$TINY_COMMON" "$TINY_FORGE" "$SPELL_ENGINE_COMMON" "$SPELL_ENGINE_FORGE" "$STRUCTURE_COMMON" "$STRUCTURE_FORGE" "$ARMOR_COMMON" "$ARMOR_FORGE" "$CLOTH_FORGE" "$PLAYER_FORGE" "$CURIOS_FORGE"; do [[ -f "$dep" ]] || { echo "[Rogues player QA] missing runtime foundation: $dep" >&2; exit 1; }; done; ARGS=("-Parmor_model_api_common_jar=$ARMOR_COMMON" "-Pstructure_pool_api_common_jar=$STRUCTURE_COMMON" "-Pspell_power_common_jar=$SPELL_POWER_COMMON" "-Pspell_engine_common_jar=$SPELL_ENGINE_COMMON" "-Ptiny_config_common_jar=$TINY_COMMON" "-Parmor_model_api_forge_jar=$ARMOR_FORGE" "-Pstructure_pool_api_forge_jar=$STRUCTURE_FORGE" "-Pspell_power_forge_jar=$SPELL_POWER_FORGE" "-Pspell_engine_forge_jar=$SPELL_ENGINE_FORGE" "-Ptiny_config_forge_jar=$TINY_FORGE" "-Pcloth_config_forge_jar=$CLOTH_FORGE" "-Pplayer_animator_forge_jar=$PLAYER_FORGE" "-Pcurios_jar=$CURIOS_FORGE")
mkdir -p "$ROBOT_DIR"; cat > "$ROBOT_DIR/RoguesInputRobot.java" <<'JAVA'
import java.awt.Robot; import java.awt.event.InputEvent; import java.awt.event.KeyEvent;
public final class RoguesInputRobot { public static void main(String[] args) throws Exception { Robot r=new Robot(); r.setAutoDelay(60); r.mouseMove(640,360); r.mousePress(InputEvent.BUTTON1_DOWN_MASK); r.mouseRelease(InputEvent.BUTTON1_DOWN_MASK); Thread.sleep(300); r.keyPress(KeyEvent.VK_W); Thread.sleep(300); for(int i=0;i<3;i++){ r.mousePress(InputEvent.BUTTON1_DOWN_MASK); r.mouseRelease(InputEvent.BUTTON1_DOWN_MASK); Thread.sleep(250); } r.keyPress(KeyEvent.VK_SPACE); Thread.sleep(160); r.keyRelease(KeyEvent.VK_SPACE); r.keyRelease(KeyEvent.VK_W); } }
JAVA
javac "$ROBOT_DIR/RoguesInputRobot.java"; mkdir -p "$(dirname "$QA_HELPER")"; cat > "$QA_HELPER" <<'JAVA'
package net.rogues.forge.client;
import net.minecraft.client.MinecraftClient; import net.minecraft.client.gui.screen.ConnectScreen; import net.minecraft.client.network.ServerAddress; import net.minecraft.client.network.ServerInfo; import net.minecraftforge.api.distmarker.Dist; import net.minecraftforge.event.TickEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraftforge.fml.common.Mod; import net.rogues.RoguesMod;
@Mod.EventBusSubscriber(modid=RoguesMod.ID, value=Dist.CLIENT)
public final class RoguesQaAutoConnect { private static int ticks; private static boolean triggered; private RoguesQaAutoConnect(){} @SubscribeEvent public static void onClientTick(TickEvent.ClientTickEvent event){ if(event.phase!=TickEvent.Phase.END||triggered)return; MinecraftClient client=MinecraftClient.getInstance(); if(client.currentScreen==null||++ticks<40)return; triggered=true; String target="127.0.0.1:25565"; System.out.println("[Rogues player QA] ROGUES_QA_AUTOCONNECT_TRIGGERED: "+target); ConnectScreen.connect(client.currentScreen,client,ServerAddress.parse(target),new ServerInfo("Rogues Player QA",target,false),false); } }
JAVA
grep -Fq 'ConnectScreen.connect(' "$QA_HELPER"; rm -rf "$FRESH/logs" "$RUN/logs"; mkdir -p "$RUN/logs" "$RUN/config"; printf 'earlyWindowControl = false\n' > "$RUN/config/fml.toml"; : > "$SERVER_LOG"; : > "$CLIENT_LOG"; rm -f "$FIFO"; mkfifo "$FIFO"; exec 9<> "$FIFO"; ( cd "$FRESH" && exec ./run.sh nogui < "$FIFO" ) > "$SERVER_LOG" 2>&1 & SERVER_PID=$!; wait_marker 'Done (' 180 'exact packaged server readiness'; export DISPLAY=:99 LIBGL_ALWAYS_SOFTWARE=1 MESA_LOADER_DRIVER_OVERRIDE=llvmpipe ALSOFT_DRIVERS=null; Xvfb "$DISPLAY" -screen 0 1280x720x24 -nolisten tcp > "$PORT/rogues-player-xvfb.log" 2>&1 & XVFB_PID=$!; sleep 1; kill -0 "$XVFB_PID" 2>/dev/null || { cat "$PORT/rogues-player-xvfb.log" >&2 || true; exit 1; }; ( gradle --no-daemon -p "$PORT" :forge:runClient "${ARGS[@]}" --args='--width 1280 --height 720' </dev/null ) > "$CLIENT_LOG" 2>&1 & CLIENT_PID=$!; wait_marker 'ROGUES_QA_AUTOCONNECT_TRIGGERED' 210 'native-client autoconnect'; wait_marker 'joined the game' 90 'real client join'; grep -Fq 'Backend library: LWJGL' "$CLIENT_LATEST" || { echo '[Rogues player QA] joined without LWJGL evidence' >&2; exit 1; }; echo '[Rogues player QA] ROGUES_REAL_PLAYER_JOIN_PASS: native LWJGL Forge client joined the exact packaged Forge server through ConnectScreen.'
send_cmd 'gamerule doMobSpawning false'; send_cmd 'time set midnight'; send_cmd 'scoreboard objectives add rogp dummy'; send_cmd 'gamemode survival @a'; send_cmd 'effect clear @a'; send_cmd 'clear @a'; send_cmd 'fill -4 99 -4 44 99 12 minecraft:stone'; send_cmd 'fill -4 100 -4 44 104 12 minecraft:air'; send_cmd 'kill @e[tag=rogp]'
send_cmd 'tp @a 20.5 100 0.5 0 0'; send_cmd 'effect give @a minecraft:instant_health 1 10 true'; send_cmd 'summon minecraft:skeleton 20.5 100 6.5 {Tags:["rogp","rogp_control_skeleton"],Silent:1b,PersistenceRequired:1b}'; sleep 6; send_cmd 'execute store result score stealth_control_hp rogp run data get entity @a[limit=1] Health 10'; send_cmd 'execute if score stealth_control_hp rogp matches ..199 run say ROGUES_STEALTH_VISIBILITY_CONTROL_PASS'; wait_marker 'ROGUES_STEALTH_VISIBILITY_CONTROL_PASS' 20 'non-stealth hostile acquisition control'; send_cmd 'kill @e[tag=rogp_control_skeleton]'; send_cmd 'effect give @a minecraft:instant_health 1 10 true'; send_cmd 'tp @a 30.5 100 0.5 0 0'; send_cmd 'effect give @a rogues:stealth 30 0 true'; send_cmd 'summon minecraft:skeleton 30.5 100 6.5 {Tags:["rogp","rogp_stealth_skeleton"],Silent:1b,PersistenceRequired:1b}'; sleep 6; send_cmd 'execute store result score stealth_hp rogp run data get entity @a[limit=1] Health 10'; send_cmd 'execute store success score stealth_present rogp run effect clear @a[limit=1] rogues:stealth'; send_cmd 'execute if score stealth_hp rogp matches 200 if score stealth_present rogp matches 1 run say ROGUES_STEALTH_VISIBILITY_RUNTIME_PASS'; wait_marker 'ROGUES_STEALTH_VISIBILITY_RUNTIME_PASS' 20 'stealth hostile visibility reduction'; send_cmd 'kill @e[tag=rogp_stealth_skeleton]'
send_cmd 'effect give @a minecraft:instant_health 1 10 true'; send_cmd 'effect give @a rogues:stealth_speed 30 0 true'; send_cmd 'effect give @a rogues:stealth 30 0 true'; send_cmd 'damage @a[limit=1] 1 minecraft:generic'; sleep 1; send_cmd 'execute store success score stealth_after_hit rogp run effect clear @a[limit=1] rogues:stealth'; send_cmd 'execute store success score speed_after_hit rogp run effect clear @a[limit=1] rogues:stealth_speed'; send_cmd 'execute if score stealth_after_hit rogp matches 0 if score speed_after_hit rogp matches 0 run say ROGUES_STEALTH_HIT_BREAK_CLEANUP_PASS'; wait_marker 'ROGUES_STEALTH_HIT_BREAK_CLEANUP_PASS' 20 'Stealth hit break and cleanup'
send_cmd 'effect clear @a'; send_cmd 'clear @a'; send_cmd 'tp @a 0.5 100 0.5 0 0'; send_cmd 'give @a minecraft:stone_sword 1'; send_cmd 'summon minecraft:husk 0.5 100 3.0 {Tags:["rogp","rogp_root_target"],NoAI:1b,Silent:1b,PersistenceRequired:1b}'; send_cmd 'effect give @a rogues:bear_trap 20 0 true'; send_cmd 'say ROGUES_ROOT_INPUT_READY'; wait_marker 'ROGUES_ROOT_INPUT_READY' 20 'ROOT input ready'; java -cp "$ROBOT_DIR" RoguesInputRobot; sleep 1; send_cmd 'execute positioned 0.5 100 0.5 if entity @a[distance=..0.25] run say ROGUES_ROOT_MOVE_BLOCK_PASS'; send_cmd 'execute store result score root_y rogp run data get entity @a[limit=1] Pos[1] 1000'; send_cmd 'execute if score root_y rogp matches 100000 run say ROGUES_ROOT_JUMP_BLOCK_PASS'; send_cmd 'execute store result score root_hp rogp run data get entity @e[tag=rogp_root_target,limit=1] Health 10'; send_cmd 'execute if score root_hp rogp matches ..199 run say ROGUES_ROOT_ATTACK_ALLOWED_PASS'; for marker in ROGUES_ROOT_MOVE_BLOCK_PASS ROGUES_ROOT_JUMP_BLOCK_PASS ROGUES_ROOT_ATTACK_ALLOWED_PASS; do wait_marker "$marker" 20 "$marker"; done
send_cmd 'effect clear @a'; send_cmd 'kill @e[tag=rogp_root_target]'; send_cmd 'clear @a'; send_cmd 'tp @a 0.5 100 0.5 0 0'; send_cmd 'give @a minecraft:stone_sword 1'; send_cmd 'summon minecraft:husk 0.5 100 3.0 {Tags:["rogp","rogp_shock_target"],NoAI:1b,Silent:1b,PersistenceRequired:1b}'; send_cmd 'effect give @a rogues:shock 20 0 true'; send_cmd 'say ROGUES_SHOCK_INPUT_READY'; wait_marker 'ROGUES_SHOCK_INPUT_READY' 20 'SHOCK input ready'; java -cp "$ROBOT_DIR" RoguesInputRobot; sleep 1; send_cmd 'execute positioned 0.5 100 0.5 if entity @a[distance=..0.25] run say ROGUES_SHOCK_MOVE_BLOCK_PASS'; send_cmd 'execute store result score shock_hp rogp run data get entity @e[tag=rogp_shock_target,limit=1] Health 10'; send_cmd 'execute if score shock_hp rogp matches 200 run say ROGUES_SHOCK_ATTACK_BLOCK_PASS'; wait_marker 'ROGUES_SHOCK_MOVE_BLOCK_PASS' 20 'SHOCK movement block'; wait_marker 'ROGUES_SHOCK_ATTACK_BLOCK_PASS' 20 'SHOCK attack block'
send_cmd 'effect clear @a rogues:shock'; send_cmd 'kill @e[tag=rogp_shock_target]'; send_cmd 'tp @a 0.5 100 0.5 0 0'; send_cmd 'summon minecraft:husk 0.5 100 3.0 {Tags:["rogp","rogp_control_target"],NoAI:1b,Silent:1b,PersistenceRequired:1b}'; send_cmd 'say ROGUES_CONTROL_INPUT_READY'; wait_marker 'ROGUES_CONTROL_INPUT_READY' 20 'control input ready'; java -cp "$ROBOT_DIR" RoguesInputRobot; sleep 1; send_cmd 'execute positioned 0.5 100 0.5 unless entity @a[distance=..0.50] run say ROGUES_CONTROL_MOVE_PASS'; send_cmd 'execute store result score control_hp rogp run data get entity @e[tag=rogp_control_target,limit=1] Health 10'; send_cmd 'execute if score control_hp rogp matches ..199 run say ROGUES_CONTROL_ATTACK_PASS'; wait_marker 'ROGUES_CONTROL_MOVE_PASS' 20 'control movement'; wait_marker 'ROGUES_CONTROL_ATTACK_PASS' 20 'control attack'
send_cmd 'effect clear @a'; send_cmd 'kill @e[tag=rogp_control_target]'; send_cmd 'tp @a 0.5 100 0.5 0 0'; send_cmd 'summon minecraft:husk 0.5 100 3.0 {Tags:["rogp","rogp_stealth_attack_target"],NoAI:1b,Silent:1b,PersistenceRequired:1b}'; send_cmd 'effect give @a rogues:stealth 30 0 true'; java -cp "$ROBOT_DIR" RoguesInputRobot; sleep 1; send_cmd 'execute store success score stealth_after_attack rogp run effect clear @a[limit=1] rogues:stealth'; send_cmd 'execute store result score stealth_attack_hp rogp run data get entity @e[tag=rogp_stealth_attack_target,limit=1] Health 10'; send_cmd 'execute if score stealth_after_attack rogp matches 0 if score stealth_attack_hp rogp matches ..199 run say ROGUES_STEALTH_ATTACK_BREAK_PASS'; wait_marker 'ROGUES_STEALTH_ATTACK_BREAK_PASS' 20 'Stealth attack break'
send_cmd 'kill @e[tag=rogp]'; send_cmd 'stop'; exec 9>&-; for _ in $(seq 1 30); do kill -0 "$SERVER_PID" 2>/dev/null || break; sleep 1; done; if kill -0 "$SERVER_PID" 2>/dev/null; then echo '[Rogues player QA] server did not stop cleanly' >&2; exit 1; fi; wait "$SERVER_PID"; SERVER_PID=''; [[ "$(sha256sum "$ROG_JAR" | awk '{print $1}')" = "$EXPECTED_SHA" ]] || { echo '[Rogues player QA] packaged release identity drifted after QA' >&2; exit 1; }
echo '[Rogues player QA] PLAYER_BEHAVIOR_ACCEPTANCE_PASS: exact packaged server + native LWJGL client proved Stealth visibility/break cleanup, ROOT movement+jump block with attacks allowed, SHOCK full-stun attack block, and positive post-clear controls.'
